from pysat.formula import CNF
from pysat.solvers import Glucose3

n = 13
all_edges = [(i,j) for i in range(n) for j in range(i+1, n)]
edge_to_idx = {e: idx+1 for idx, e in enumerate(all_edges)}
num_edge_vars = len(all_edges)

# Color variables
color_vars = {v: num_edge_vars + 1 + v for v in range(n)}
num_vars = num_edge_vars + n

cnf = CNF()

# Fixed edges
cnf.append([edge_to_idx[(0,1)]])
cnf.append([edge_to_idx[(0,8)]])

# Bipartiteness: for each edge, colors must differ
for (i,j) in all_edges:
    e = edge_to_idx[(i,j)]
    ci = color_vars[i]
    cj = color_vars[j]
    cnf.append([-e, ci, cj])
    cnf.append([-e, -ci, -cj])

# No 4-cycles
for a in range(n):
    for b in range(a+1, n):
        for c in range(b+1, n):
            for d in range(c+1, n):
                patterns = [
                    [(a,b),(b,c),(c,d),(d,a)],
                    [(a,b),(b,d),(d,c),(c,a)],
                    [(a,c),(c,b),(b,d),(d,a)],
                ]

                for pattern in patterns:
                    norm_edges = []
                    valid = True
                    for (u,v) in pattern:
                        if u == v:
                            valid = False
                            break
                        norm_edges.append((min(u,v), max(u,v)))
                    if not valid:
                        continue

                    if all(e in edge_to_idx for e in norm_edges):
                        cnf.append([-edge_to_idx[e] for e in norm_edges])

print(f"Variables: {num_vars}, Clauses: {len(cnf.clauses)}")

# At-least-8 constraint using sequential counter
k = 8
s_idx = num_vars + 1
s = {}
for i in range(1, num_edge_vars + 1):
    for j in range(1, k + 1):
        s[(i,j)] = s_idx
        s_idx += 1

total_vars = s_idx - 1

# Initialize i=1
cnf.append([-s[(1,1)], edge_to_idx[all_edges[0]]])
cnf.append([s[(1,1)], -edge_to_idx[all_edges[0]]])
for j in range(2, k+1):
    cnf.append([-s[(1,j)]])

# For i>1:
for i in range(2, num_edge_vars + 1):
    xi = edge_to_idx[all_edges[i-1]]
    # j=1
    cnf.append([-s[(i-1,1)], s[(i,1)]])
    cnf.append([-xi, s[(i,1)]])
    cnf.append([-s[(i,1)], xi, s[(i-1,1)]])

    # j>1
    for j in range(2, k+1):
        cnf.append([-s[(i-1,j)], s[(i,j)]])
        cnf.append([-xi, -s[(i-1,j-1)], s[(i,j)]])
        cnf.append([-s[(i,j)], s[(i-1,j)], xi])
        cnf.append([-s[(i,j)], s[(i-1,j)], s[(i-1,j-1)]])

# At least k edges
cnf.append([s[(num_edge_vars, k)]])

print(f"Total variables: {total_vars}, Total clauses: {len(cnf.clauses)}")

# Solve
solver = Glucose3()
for clause in cnf.clauses:
    solver.add_clause(clause)

result = solver.solve()
print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    solution_edges = []
    for e, idx in edge_to_idx.items():
        if model[idx-1] > 0:
            solution_edges.append(e)

    print(f"Number of edges: {len(solution_edges)}")
    print(f"Edges: {sorted(solution_edges)}")

    colors = {}
    for v in range(n):
        if model[color_vars[v]-1] > 0:
            colors[v] = 1
        else:
            colors[v] = 0
    print(f"Colors: {colors}")

    # Verify
    adj = {v: set() for v in range(n)}
    for (u,v) in solution_edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check bipartiteness
    ok = True
    for (u,v) in solution_edges:
        if colors[u] == colors[v]:
            print(f"ERROR: Edge ({u},{v}) has same color!")
            ok = False

    # Check 4-cycles
    found_4cycle = False
    for a in range(n):
        for b in adj[a]:
            if b <= a: continue
            for c in adj[b]:
                if c <= b or c == a: continue
                for d in adj[c]:
                    if d <= c or d == a or d == b: continue
                    if d in adj[a]:
                        print(f"Found 4-cycle: {a}-{b}-{c}-{d}-{a}")
                        found_4cycle = True

    if not found_4cycle:
        print("No 4-cycles found!")

    if ok and not found_4cycle:
        print("Solution is valid!")
else:
    print("UNSAT")
    # Let's try with k=7
    print("\nTrying with k=7...")
